let bend = sin(p.y * 2.4 + t * 0.22 + seed.x * 1.7) * 0.28 + sin(p.y * 1.15 - t * 0.14) * 0.13;
let cursor = pointer * vec2f(0.745, -1.13);
let offset = p - cursor;
let touch = exp(-dot(offset, offset) * 4.0) * (pointer.x * 0.20 - pointer.y * 0.12);
return clamp(p.x * 0.9 + bend + touch, -0.93, 0.93);

let drift = vec2f(t * 0.009, sin(t * 0.065) * 0.06);
let q = p * vec2f(1.8, 1.2) + seed.xy * 3.0 + drift;
let broad = noise2(q) * 0.52;
let ridge = (1.0 - abs(noise2(q * 2.1 + vec2f(3.0, 7.0)))) * 0.28;
let detail = noise2(q * 4.8) * 0.07;
let touch = exp(-dot(p - pointer * 0.55, p - pointer * 0.55) * 3.0) * 0.045;
return clamp(broad + ridge + detail + touch - 0.14, -0.9, 0.9);
